def merge_with(func, *dicts, **kwargs):
    """ Merge dictionaries or Mappings and apply function to combined values

    A key may occur in more than one dict, and all values mapped from the key
    will be passed to the function as a list, such as func([val1, val2, ...]).

    Works with any Mapping type, returning the same type as the first argument.

    >>> merge_with(sum, {1: 1, 2: 2}, {1: 10, 2: 20})
    {1: 11, 2: 22}

    >>> merge_with(first, {1: 1, 2: 2}, {2: 20, 3: 30})  # doctest: +SKIP
    {1: 1, 2: 2, 3: 30}

    See Also:
        merge
    """
    if len(dicts) == 1 and not isinstance(dicts[0], dict):
        dicts = dicts[0]

    # Determine factory from first argument or kwargs
    factory = kwargs.pop('factory', None)
    if factory is None and dicts:
        first = dicts[0]
        if isinstance(first, Mapping):
            factory = type(first)
        else:
            factory = dict

    if factory is None:
        factory = dict

    result = factory()
    for d in dicts:
        for k, v in iteritems(d):
            if k not in result:
                result[k] = [v]
            else:
                result[k].append(v)
    return valmap(func, result, factory)

